: "pmh:oai:scholarworks.waldenu.edu:dissertations-6821", "doi": null, "is_oa": true, "landing_page_url": "https://scholarworks.waldenu.edu/dissertations/5542", "pdf_url": "https://scholarworks.waldenu.edu/cgi/viewcontent.cgi?article=6821&context=dissertations", "source": {"id": "https://openalex.org/S4377196507", "display_name": "ScholarWorks (Walden University)", "issn_l": null, "issn": null, "is_oa": false, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I80046288", "host_organization_name": "Walden University", "host_organization_lineage": ["https://openalex.org/I80046288"], "host_organization_lineage_names": [], "type": "repository"}, "license": null, "license_id": null, "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": "Walden Dissertations and Doctoral Studies", "raw_type": "text"}, "abstract": "The threat and occurrence of terrorist attacks have increased in the United States since September 2011, heightening concerns for weaponized anthrax, other biological pathogens, and epidemics and pandemics. Early decisions and funding levels in local public health agencies can be the first line of defense or first point of failure; yet little is understood about how decisions are made when there are budget cuts before a biological event happens. Using Lindblom's conceptualization of limited rational choice theory, the purpose of this single case study was to understand how a local public health official made decisions after budget cuts in a single public health entity in the mid-Atlantic area of the United States. Data were collected through an interview with 1 public health official and publicly available plans, procedures, and funding documents. These data were inductively coded and then subjected to Braun and Clarke's thematic analysis procedure. Findings indicated that the public health agency's ability to make the best decisions were negatively impacted by limited resources, though adequate planning before a catastrophic event, active and continual communication with stakeholders, and clarity about financial and resource needs can partially offset the impact of budgetary reductions. The implications for social change include recommendations to anticipate and address the needs of the public health system through decision making to protect the health care community and the reduction or elimination of the spread of disease in the wake of a biological incident."}]", "excerpt_truncated": true, "source_sha256": "922103278d52a7a9fdf55064e7c6b4e72131b262191f989298fd90ae4884bc27", "verification_required": true, "topic_domain": "continuity_rationale", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s40865-015-0013-2", "doi:10.1111/j.1529-1006.2006.00026.x", "openalex:W1916301808", "openalex:W2025605773"], "source_candidates": ["https://doi.org/10.1007/s40865-015-0013-2", "https://doi.org/10.1111/j.1529-1006.2006.00026.x", "https://journals.sagepub.com/doi/pdf/10.1111/j.1529-1006.2006.00026.x", "https://scholarworks.waldenu.edu/dissertations/5542", "https://scholarworks.waldenu.edu/cgi/viewcontent.cgi?article=6821&context=dissertations"], "source_candidate_identities": {}}

